CREATE OR REPLACE FUNCTION public.sealed_product_assert_image_release_complete_v1(p_image_release_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_release public.sealed_product_image_releases%rowtype;
  v_source_member_count integer;
  v_coverage_evidence_count integer;
  v_eligible_evidence_count integer;
  v_release_member_count integer;
  v_computed_manifest_fingerprint text;
begin
  select * into v_release
  from public.sealed_product_image_releases
  where id = p_image_release_id;

  if not found then
    raise exception 'image release does not exist' using errcode = '23503';
  end if;

  select count(*)::integer into v_source_member_count
  from public.sealed_product_release_members price_member
  where price_member.release_id = v_release.source_price_release_id;

  if v_source_member_count <= 0 then
    raise exception 'source price release has no members' using errcode = '23514';
  end if;

  select
    count(*)::integer,
    count(*) filter (where evidence.classification in (
      'exact_image_ready', 'shared_bytes_exact_variant'
    ))::integer
  into v_coverage_evidence_count, v_eligible_evidence_count
  from public.sealed_product_image_evidence evidence
  where evidence.game_key = v_release.game_key
    and evidence.source_plan_fingerprint = v_release.source_plan_fingerprint
    and evidence.coverage_fingerprint = v_release.coverage_fingerprint;

  if v_coverage_evidence_count <> v_source_member_count then
    raise exception 'coverage evidence count mismatch: expected %, found %',
      v_source_member_count, v_coverage_evidence_count using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.sealed_product_release_members price_member
    where price_member.release_id = v_release.source_price_release_id
      and not exists (
        select 1
        from public.sealed_product_image_evidence evidence
        where evidence.source_release_member_id = price_member.id
          and evidence.game_key = v_release.game_key
          and evidence.variant_id = price_member.variant_id
          and evidence.source_mapping_id = price_member.source_mapping_id
          and evidence.source_plan_fingerprint = v_release.source_plan_fingerprint
          and evidence.coverage_fingerprint = v_release.coverage_fingerprint
      )
  ) or exists (
    select 1
    from public.sealed_product_image_evidence evidence
    where evidence.game_key = v_release.game_key
      and evidence.source_plan_fingerprint = v_release.source_plan_fingerprint
      and evidence.coverage_fingerprint = v_release.coverage_fingerprint
      and not exists (
        select 1
        from public.sealed_product_release_members price_member
        where price_member.id = evidence.source_release_member_id
          and price_member.release_id = v_release.source_price_release_id
          and price_member.variant_id = evidence.variant_id
          and price_member.source_mapping_id = evidence.source_mapping_id
      )
  ) then
    raise exception 'coverage evidence does not exactly match source price members'
      using errcode = '23514';
  end if;

  if v_eligible_evidence_count <= 0
     or v_release.expected_member_count <> v_eligible_evidence_count then
    raise exception 'eligible image evidence count mismatch: expected %, found %',
      v_release.expected_member_count, v_eligible_evidence_count
      using errcode = '23514';
  end if;

  select count(*)::integer into v_release_member_count
  from public.sealed_product_image_release_members member
  where member.image_release_id = p_image_release_id;

  if v_release_member_count <> v_eligible_evidence_count then
    raise exception 'image release member count mismatch: expected %, found %',
      v_eligible_evidence_count, v_release_member_count using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.sealed_product_image_evidence evidence
    where evidence.game_key = v_release.game_key
      and evidence.source_plan_fingerprint = v_release.source_plan_fingerprint
      and evidence.coverage_fingerprint = v_release.coverage_fingerprint
      and evidence.classification in (
        'exact_image_ready', 'shared_bytes_exact_variant'
      )
      and not exists (
        select 1
        from public.sealed_product_image_release_members member
        join public.sealed_product_variant_image_assertions assertion
          on assertion.id = member.image_assertion_id
         and assertion.game_key = member.game_key
         and assertion.variant_id = member.variant_id
        where member.image_release_id = p_image_release_id
          and member.variant_id = evidence.variant_id
          and assertion.image_evidence_id = evidence.id
      )
  ) then
    raise exception 'image release omits eligible audited evidence'
      using errcode = '23514';
  end if;

  v_computed_manifest_fingerprint :=
    public.sealed_product_image_release_manifest_fingerprint_v1(
      p_image_release_id
    );
  if v_computed_manifest_fingerprint is null
     or v_computed_manifest_fingerprint <> v_release.manifest_fingerprint then
    raise exception 'image release manifest does not match canonical member set'
      using errcode = '23514';
  end if;

  return v_computed_manifest_fingerprint;
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_product_freeze_image_release_v1(p_image_release_id uuid, p_expected_manifest_fingerprint text, p_frozen_by uuid)
 RETURNS sealed_product_image_releases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_release public.sealed_product_image_releases%rowtype;
  v_computed_manifest_fingerprint text;
begin
  if p_frozen_by is null then
    raise exception 'frozen_by is required' using errcode = '22004';
  end if;

  select * into v_release
  from public.sealed_product_image_releases
  where id = p_image_release_id
  for update;

  if not found or v_release.release_state <> 'draft' then
    raise exception 'image release must exist and be draft' using errcode = '23514';
  end if;
  if v_release.manifest_fingerprint <> p_expected_manifest_fingerprint then
    raise exception 'image release manifest fingerprint mismatch'
      using errcode = '23514';
  end if;

  lock table public.sealed_product_release_members in share mode;
  lock table public.sealed_product_image_evidence in share mode;
  lock table public.sealed_product_variant_image_assertions in share mode;

  v_computed_manifest_fingerprint :=
    public.sealed_product_assert_image_release_complete_v1(p_image_release_id);
  if v_computed_manifest_fingerprint <> p_expected_manifest_fingerprint then
    raise exception 'computed image release manifest fingerprint mismatch'
      using errcode = '23514';
  end if;

  update public.sealed_product_image_releases
  set release_state = 'frozen', frozen_by = p_frozen_by, frozen_at = now()
  where id = p_image_release_id
  returning * into v_release;

  return v_release;
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_product_guard_image_evidence_insert_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if exists (
    select 1
    from public.sealed_product_image_releases image_release
    where image_release.game_key = new.game_key
      and image_release.source_plan_fingerprint = new.source_plan_fingerprint
      and image_release.coverage_fingerprint = new.coverage_fingerprint
      and image_release.release_state = 'frozen'
  ) then
    raise exception 'cannot append evidence to a frozen image release audit set'
      using errcode = '55000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_product_guard_image_release_insert_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.release_state <> 'draft'
     or new.frozen_by is not null
     or new.frozen_at is not null then
    raise exception 'image release must be inserted in draft state'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.sealed_product_releases price_release
    where price_release.id = new.source_price_release_id
      and price_release.game_key = new.game_key
      and price_release.release_state = 'frozen'
  ) then
    raise exception 'image release source price release must be frozen'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_product_guard_image_release_mutation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'sealed product image releases cannot be deleted'
      using errcode = '55000';
  end if;

  if old.release_state = 'draft'
     and new.release_state = 'frozen'
     and new.frozen_by is not null
     and new.frozen_at is not null
     and (to_jsonb(new) - 'release_state' - 'frozen_by' - 'frozen_at')
       = (to_jsonb(old) - 'release_state' - 'frozen_by' - 'frozen_at') then
    if not exists (
      select 1
      from public.sealed_product_releases price_release
      where price_release.id = new.source_price_release_id
        and price_release.game_key = new.game_key
        and price_release.release_state = 'frozen'
    ) then
      raise exception 'image release source price release must remain frozen'
        using errcode = '23514';
    end if;
    return new;
  end if;

  raise exception 'sealed product image release mutation is not an authorized freeze transition'
    using errcode = '55000';
end;
$function$

CREATE OR REPLACE FUNCTION public.sealed_product_set_active_image_release_v1(p_target_image_release_id uuid, p_expected_current_image_release_id uuid, p_changed_by uuid)
 RETURNS TABLE(game_key text, active_image_release_id uuid, previous_image_release_id uuid, changed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_release public.sealed_product_image_releases%rowtype;
  v_current_release_id uuid;
  v_current_price_release_id uuid;
  v_computed_manifest_fingerprint text;
begin
  if p_changed_by is null then
    raise exception 'changed_by is required' using errcode = '22004';
  end if;

  select * into v_release
  from public.sealed_product_image_releases
  where id = p_target_image_release_id;

  if not found or v_release.release_state <> 'frozen' then
    raise exception 'target image release must exist and be frozen'
      using errcode = '23514';
  end if;

  lock table public.sealed_product_release_members in share mode;
  lock table public.sealed_product_image_evidence in share mode;
  lock table public.sealed_product_variant_image_assertions in share mode;

  v_computed_manifest_fingerprint :=
    public.sealed_product_assert_image_release_complete_v1(
      p_target_image_release_id
    );
  if v_computed_manifest_fingerprint <> v_release.manifest_fingerprint then
    raise exception 'computed image release manifest fingerprint mismatch'
      using errcode = '23514';
  end if;

  lock table public.sealed_product_release_pointer in share mode;

  select price_pointer.release_id into v_current_price_release_id
  from public.sealed_product_release_pointer price_pointer
  where price_pointer.game_key = v_release.game_key
  for share;

  if v_current_price_release_id is distinct from v_release.source_price_release_id then
    raise exception 'target image release is not bound to the active price release'
      using errcode = '23514';
  end if;

  lock table public.sealed_product_image_release_pointer in exclusive mode;

  select pointer.image_release_id into v_current_release_id
  from public.sealed_product_image_release_pointer pointer
  where pointer.game_key = v_release.game_key
  for update;

  if v_current_release_id is distinct from p_expected_current_image_release_id then
    raise exception 'active image release changed concurrently'
      using errcode = '40001';
  end if;

  insert into public.sealed_product_image_release_pointer (
    game_key, image_release_id, previous_image_release_id,
    pointer_contract_version, changed_by, changed_at
  ) values (
    v_release.game_key, p_target_image_release_id, v_current_release_id,
    'SEALED_PRODUCT_IMAGE_RELEASE_POINTER_V1', p_changed_by, now()
  )
  on conflict (game_key) do update set
    image_release_id = excluded.image_release_id,
    previous_image_release_id = excluded.previous_image_release_id,
    pointer_contract_version = excluded.pointer_contract_version,
    changed_by = excluded.changed_by,
    changed_at = excluded.changed_at;

  return query
  select pointer.game_key, pointer.image_release_id,
    pointer.previous_image_release_id, pointer.changed_at
  from public.sealed_product_image_release_pointer pointer
  where pointer.game_key = v_release.game_key;
end;
$function$
